from __future__ import annotations

from pathlib import Path
import base64
import hashlib
import zlib

ROOT = Path(__file__).resolve().parent
TAB = ROOT / "dashboard" / "src" / "pages" / "inventory" / "TabTransfers.tsx"
WAREHOUSE = ROOT / "wa_backend" / "api" / "warehouse.py"

BASELINE_SHA256 = '43ce281eed53faa95c5a4a2bac4b1d1ad489b883d0c8b52c82c78a3098107889'
HARDENED_SHA256 = 'afd6a3b26a92242645582b0ef672d4559a81410e40a4699dbd87112be3e8c5ad'
HARDENED_TAB = zlib.decompress(
    base64.b64decode('')
).decode("utf-8")

OLD_BACKEND = '@router.get(\n    "/warehouse/unified/transfer/locations",\n    response_model=List[UnifiedTransferLocationItem],\n    status_code=200,\n)\nasync def list_unified_transfer_locations(\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin),\n):\n    company_id = current_admin.company_id\n\n    rows = (\n        await db.execute(\n            select(\n                InventoryLocation.id,\n                InventoryLocation.name,\n                InventoryLocation.code,\n                InventoryLocation.location_type,\n                InventoryLocation.vehicle_id,\n            )\n            .filter(\n                InventoryLocation.company_id == company_id,\n                InventoryLocation.is_active.is_(True),\n                InventoryLocation.location_type.in_(\n                    [\'WAREHOUSE\', \'VEHICLE\']\n                ),\n            )\n            .order_by(\n                case(\n                    (InventoryLocation.location_type == \'WAREHOUSE\', 0),\n                    else_=1,\n                ),\n                InventoryLocation.name.asc(),\n                InventoryLocation.id.asc(),\n            )\n        )\n    ).all()\n\n    return [\n        {\n            "id": int(row.id),\n            "name": str(row.name),\n            "code": str(row.code),\n            "location_type": str(row.location_type),\n            "vehicle_id": (\n                int(row.vehicle_id)\n                if row.vehicle_id is not None\n                else None\n            ),\n        }\n        for row in rows\n    ]\n'
NEW_BACKEND = '@router.get(\n    "/warehouse/unified/transfer/locations",\n    response_model=List[UnifiedTransferLocationItem],\n    status_code=200,\n)\nasync def list_unified_transfer_locations(\n    search: Optional[str] = Query(\n        default=None,\n        min_length=2,\n        max_length=100,\n    ),\n    limit: int = Query(default=50, ge=1, le=100),\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin),\n):\n    company_id = current_admin.company_id\n    clean_search = (search or "").strip().lower()\n\n    stmt = (\n        select(\n            InventoryLocation.id,\n            InventoryLocation.name,\n            InventoryLocation.code,\n            InventoryLocation.location_type,\n            InventoryLocation.vehicle_id,\n        )\n        .filter(\n            InventoryLocation.company_id == company_id,\n            InventoryLocation.is_active.is_(True),\n            InventoryLocation.location_type.in_(\n                [\'WAREHOUSE\', \'VEHICLE\']\n            ),\n        )\n    )\n\n    if clean_search:\n        pattern = f"%{_escape_like(clean_search)}%"\n        stmt = stmt.filter(\n            or_(\n                func.lower(InventoryLocation.name).like(\n                    pattern,\n                    escape="\\\\",\n                ),\n                func.lower(InventoryLocation.code).like(\n                    pattern,\n                    escape="\\\\",\n                ),\n            )\n        )\n\n    rows = (\n        await db.execute(\n            stmt.order_by(\n                case(\n                    (InventoryLocation.location_type == \'WAREHOUSE\', 0),\n                    else_=1,\n                ),\n                InventoryLocation.name.asc(),\n                InventoryLocation.id.asc(),\n            ).limit(limit)\n        )\n    ).all()\n\n    return [\n        {\n            "id": int(row.id),\n            "name": str(row.name),\n            "code": str(row.code),\n            "location_type": str(row.location_type),\n            "vehicle_id": (\n                int(row.vehicle_id)\n                if row.vehicle_id is not None\n                else None\n            ),\n        }\n        for row in rows\n    ]\n'


def fail(message: str) -> None:
    raise SystemExit(f"PATCH_ABORTED: {message}")


def normalize(text: str) -> str:
    return text.replace("\r\n", "\n")


def sha256_text(text: str) -> str:
    return hashlib.sha256(
        normalize(text).encode("utf-8")
    ).hexdigest()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        print(f"UNCHANGED={label}")
        return text
    count = text.count(old)
    if count != 1:
        fail(f"{label}: expected 1 match, found {count}")
    print(f"PATCHED={label}")
    return text.replace(old, new, 1)


for path in (TAB, WAREHOUSE):
    if not path.exists():
        fail(f"Missing file: {path.relative_to(ROOT)}")


tab = normalize(TAB.read_text(encoding="utf-8"))
tab_sha = sha256_text(tab)

if tab_sha == HARDENED_SHA256:
    print("UNCHANGED=TabTransfers.tsx")
elif tab_sha == BASELINE_SHA256:
    TAB.write_text(HARDENED_TAB, encoding="utf-8")
    print("PATCHED=TabTransfers.tsx")
else:
    fail(
        "TabTransfers.tsx differs from the exact Stage-3B2 baseline. "
        f"Current SHA256={tab_sha}"
    )


warehouse = normalize(WAREHOUSE.read_text(encoding="utf-8"))
warehouse = replace_once(
    warehouse,
    OLD_BACKEND,
    NEW_BACKEND,
    "bounded_searchable_transfer_locations",
)
WAREHOUSE.write_text(warehouse, encoding="utf-8")


tab = normalize(TAB.read_text(encoding="utf-8"))
warehouse = normalize(WAREHOUSE.read_text(encoding="utf-8"))

checks = {
    "SOURCE_CURSOR_CONSUMED": (
        'params.set("cursor", pageCursor)' in tab
        and "sourceProductsNextCursor" in tab
        and "تحميل المزيد" in tab
    ),
    "SOURCE_CURSOR_RACE_GUARD": (
        "sourceProductsRequestSeq.current" in tab
    ),
    "SOURCE_APPEND_DEDUP": (
        "new Map<number, TransferSourceInventoryItem>()" in tab
    ),
    "LOCATION_SEARCH_UI": (
        "transferLocationSearchInput" in tab
        and "transferLocationSearch" in tab
    ),
    "LOCATION_SEARCH_SERVER": (
        'params.set("search", transferLocationSearch)' in tab
    ),
    "LOCATION_RESULTS_MERGED": (
        "new Map<number, TransferLocationOption>()" in tab
    ),
    "LOCATION_ENDPOINT_BOUNDED": (
        "limit: int = Query(default=50, ge=1, le=100)" in warehouse
        and ".limit(limit)" in warehouse
    ),
    "LOCATION_ENDPOINT_SEARCHABLE": (
        "func.lower(InventoryLocation.name).like" in warehouse
        and "func.lower(InventoryLocation.code).like" in warehouse
    ),
    "LOCATION_TENANT_SCOPE": (
        "InventoryLocation.company_id == company_id" in warehouse
    ),
    "NO_FRONTEND_COMPANY_ID": "company_id" not in tab,
    "NO_FRONTEND_ANY": ": any" not in tab and "any[]" not in tab,
}

failed = [name for name, ok in checks.items() if not ok]
if failed:
    fail(f"Static verification failed: {failed}")

print("TRANSFER_SOURCE_CURSOR_SCALABILITY=OK")
print("TRANSFER_SOURCE_CURSOR_RACE_GUARD=OK")
print("TRANSFER_LOCATION_SEARCH_SCALABILITY=OK")
print("TRANSFER_LOCATION_RESULT_MERGE=OK")
print("TRANSFER_LOCATION_TENANT_SCOPE=OK")
print("TRANSFER_SCALABILITY_HARDENING=OK")
